manifest=[]
def archived(archive,member):
    p=A/'files'/archive
    with zipfile.ZipFile(p) as z:raw=z.read(member)
    manifest.append(dict(id=f'S2-EV{len(manifest)+1:02}',path='assets/files/'+archive,archive_member=member,file_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),member_sha256=hashlib.sha256(raw).hexdigest()))
    return json.loads(raw),manifest[-1]['id']
